import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry rejection diagnostics', () => {
  it('reports the location type failure without exposing 123456789 (specs/hal-engine-tool-input-validation/spec.md#10)', async () => {
    const registry = new ToolRegistry();
    const warnings: unknown[] = [];
    setLogger({
      debug() {},
      info() {},
      warn(category, message, fields) {
        warnings.push({category, message, fields});
      },
      error() {},
    });
    try {
      registry.register(
        {
          name: 'weather',
          description: 'Get weather',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
        },
        async () => {
          throw new Error('Rejected input reached executor');
        }
      );
      const response = await registry.execute('weather', {location: 123456789});
      const diagnostics = JSON.stringify({response, warnings});

      expect({
        warningCount: warnings.length,
        result: response.result,
        warning: JSON.stringify(warnings),
        leaksValue: diagnostics.includes('123456789'),
      }).toEqual({
        warningCount: 1,
        result: expect.stringMatching(/location.*string/),
        warning: expect.stringMatching(/location.*string/),
        leaksValue: false,
      });
    } finally {
      setLogger();
    }
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registryDiagnostics.test.ts --runInBand"
